begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(14);
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','owner@test.invalid');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"service_role"}',true);
select public.provision_owner('11111111-1111-4111-8111-111111111111');
update public.app_settings set paused=false,scraping_enabled=true,provider_account_id='provider-owner',monthly_budget_usd=0.50,max_run_charge_usd=0.25;
select public.worker_record_balance('11111111-1111-4111-8111-111111111111','provider-owner',5,0,date_trunc('month',now() at time zone 'UTC')::date);
insert into public.workspaces(id,owner_user_id,name,slug) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','Test','test');
insert into public.workspace_members(workspace_id,user_id) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111');
insert into public.creators(id,username) select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'creator_'||n from generate_series(1,41) n;
insert into public.workspace_creators(workspace_id,creator_id) select 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',id from public.creators;
select public.queue_creator_jobs('11111111-1111-4111-8111-111111111111',(select array_agg(id) from public.creators),'manual');
select is((select count(*)::integer from public.scrape_jobs),3,'durable <=20 batches');
select ok((select max(requested_profiles_count)<=20 from public.scrape_jobs),'batch size enforced');
select is(cardinality(public.queue_creator_jobs('11111111-1111-4111-8111-111111111111',(select array_agg(id) from public.creators),'manual')),0,'busy creators deduped');
create temporary table claims(n integer primary key,data jsonb);
insert into claims values(1,public.worker_claim_dispatch('11111111-1111-4111-8111-111111111111',true,'actor-id','manual'));
insert into claims values(2,public.worker_claim_dispatch('11111111-1111-4111-8111-111111111111',true,'actor-id','manual'));
select is((select sum(reserved_usd) from public.scrape_jobs),0.50::numeric,'reserve actual cap not modeled item estimate');
select is(public.worker_claim_dispatch('11111111-1111-4111-8111-111111111111',true,'actor-id','manual')->>'reason','concurrency_limit','two maximum active runs');
select public.worker_start_uncertain((data->'job'->>'id')::uuid,(data->'job'->>'dispatch_nonce')::uuid) from claims where n=1;
select is(public.worker_claim_dispatch('11111111-1111-4111-8111-111111111111',true,'actor-id','manual')->>'reason','unreconciled_charges','uncertain acceptance blocks dispatch');
select is((select sum(reserved_usd) from public.scrape_jobs),0.50::numeric,'uncertain reservation not released');
select public.worker_attach_run((data->'job'->>'id')::uuid,(data->'job'->>'dispatch_nonce')::uuid,'run-1','actor-id','provider-owner','dataset-1') from claims where n=1;
select throws_ok($$select public.worker_reconcile_run((data->'job'->>'id')::uuid,'run-1','wrong-actor','provider-owner','SUCCEEDED','dataset-1',0.01) from claims where n=1$$,'42501','run_identity_mismatch','provider identity verified');
select public.worker_reconcile_run((data->'job'->>'id')::uuid,'run-1','actor-id','provider-owner','SUCCEEDED','dataset-1',null) from claims where n=1;
select ok((select actual_cost_usd is null from public.scrape_jobs where actor_run_id='run-1'),'missing usage remains unknown');
select is(public.worker_claim_dispatch('11111111-1111-4111-8111-111111111111',true,'actor-id','manual')->>'reason','unreconciled_charges','missing final cost blocks dispatch');
select public.worker_reconcile_run((data->'job'->>'id')::uuid,'run-1','actor-id','provider-owner','SUCCEEDED','dataset-1',0.02) from claims where n=1;
select is((select actual_cost_usd from public.scrape_jobs where actor_run_id='run-1'),0.02::numeric,'authoritative usage accepted');
create temporary table processing as select public.worker_claim_processing((data->'job'->>'id')::uuid) data from claims where n=1;
select public.worker_ingest_page((data->'job'->>'id')::uuid,(data->'job'->>'lease_token')::uuid,0,
 jsonb_build_array(jsonb_build_object('creator_id',data->'creators'->0->>'id','username',data->'creators'->0->>'username','fetched_at',data->'job'->>'result_fetched_at','provider','test','shortcode','TEST123','reel_url','https://www.instagram.com/reel/TEST123/','published_at','2026-11-01T00:00:00Z','views',100,'likes',null,'comments',0,'views_state','known','likes_state','hidden','comments_state','known')),
 '[]',1,true) from processing;
select is((select count(*)::integer from public.reel_metric_snapshots),1,'daily snapshot written');
select is((public.worker_ingest_page((data->'job'->>'id')::uuid,(data->'job'->>'lease_token')::uuid,0,'[]','[]',1,true)->>'duplicate')::boolean,true,'duplicate page idempotent') from processing;
select public.worker_finish_processing((data->'job'->>'id')::uuid,(data->'job'->>'lease_token')::uuid) from processing;
select is((select status from public.scrape_jobs where actor_run_id='run-1'),'partial','empty profiles not guessed successful/private');
select * from finish(); rollback;
